SELECT content_id AS contentId
FROM user_behavior_event
WHERE user_identity = #{userIdentity}
ORDER BY created_time DESC
LIMIT #{limit}

SELECT COUNT(1)
FROM user_behavior_event
WHERE user_identity = #{userIdentity}
AND created_time >= #{since}

SELECT user_identity
FROM user_behavior_event
WHERE created_time >= #{since}
GROUP BY user_identity
ORDER BY MAX(created_time) DESC
LIMIT #{limit}
